{"name": "create_salary_alerts_table_and_trigger", "query": "
-- ============================================================
-- SUPPORT TABLE: salary_alerts
-- Captures every newly inserted salary that exceeds $120,000
-- ============================================================
CREATE TABLE IF NOT EXISTS employees.salary_alerts (
    alert_id       BIGSERIAL    PRIMARY KEY,
    employee_id    BIGINT       NOT NULL REFERENCES employees.employee(id),
    salary_amount  BIGINT       NOT NULL,
    alert_date     DATE         NOT NULL DEFAULT CURRENT_DATE,
    status         VARCHAR(20)  NOT NULL DEFAULT 'new',
    created_at     TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);

COMMENT ON TABLE  employees.salary_alerts                IS 'Auto-populated alerts for salaries inserted above the $120,000 threshold.';
COMMENT ON COLUMN employees.salary_alerts.alert_id       IS 'Surrogate primary key (auto-increment).';
COMMENT ON COLUMN employees.salary_alerts.employee_id    IS 'FK to the employee whose salary triggered the alert.';
COMMENT ON COLUMN employees.salary_alerts.salary_amount  IS 'The salary amount that crossed the threshold.';
COMMENT ON COLUMN employees.salary_alerts.alert_date     IS 'Calendar date the alert was raised.';
COMMENT ON COLUMN employees.salary_alerts.status         IS 'Workflow status: new → reviewed → resolved.';

-- ============================================================
-- TRIGGER FUNCTION: fn_high_salary_alert
-- Fires AFTER INSERT on employees.salary
-- ============================================================
CREATE OR REPLACE FUNCTION employees.fn_high_salary_alert()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
    -- Only act on records whose amount exceeds the executive threshold
    IF NEW.amount > 120000 THEN
        INSERT INTO employees.salary_alerts
            (employee_id, salary_amount, alert_date, status)
        VALUES
            (NEW.employee_id, NEW.amount, CURRENT_DATE, 'new');

        RAISE NOTICE 'HIGH SALARY ALERT — employee_id=%, amount=%, date=%',
            NEW.employee_id, NEW.amount, CURRENT_DATE;
    END IF;
    RETURN NEW;
END;
$$;

COMMENT ON FUNCTION employees.fn_high_salary_alert() IS
    'Trigger function: inserts a salary_alerts row whenever a salary INSERT exceeds $120,000.';

-- ============================================================
-- TRIGGER: high_salary_alert
-- Attached to employees.salary — fires per row after every INSERT
-- ============================================================
DROP TRIGGER IF EXISTS high_salary_alert ON employees.salary;

CREATE TRIGGER high_salary_alert
    AFTER INSERT ON employees.salary
    FOR EACH ROW
    EXECUTE FUNCTION employees.fn_high_salary_alert();

COMMENT ON TRIGGER high_salary_alert ON employees.salary IS
    'Fires after each INSERT; routes high-salary records (>$120,000) to salary_alerts.';
"}

{"name": "create_monthly_reports_and_procedure", "query": "
-- ============================================================
-- SUPPORT TABLE: monthly_reports
-- Persisted snapshot produced by generate_monthly_report()
-- ============================================================
CREATE TABLE IF NOT EXISTS employees.monthly_reports (
    report_id         BIGSERIAL    PRIMARY KEY,
    report_date       DATE         NOT NULL,
    department_count  INTEGER      NOT NULL,
    total_employees   INTEGER      NOT NULL,
    avg_salary        DECIMAL(12,2) NOT NULL,
    generated_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),

    CONSTRAINT uq_monthly_report_date UNIQUE (report_date)
);

COMMENT ON TABLE  employees.monthly_reports                  IS 'One summary row per report run; generated by generate_monthly_report().';
COMMENT ON COLUMN employees.monthly_reports.report_id        IS 'Surrogate primary key (auto-increment).';
COMMENT ON COLUMN employees.monthly_reports.report_date      IS 'The logical reporting date passed to the procedure (unique per run).';
COMMENT ON COLUMN employees.monthly_reports.department_count IS 'Total number of departments at generation time.';
COMMENT ON COLUMN employees.monthly_reports.total_employees  IS 'Active employee count (open-ended salary record) at generation time.';
COMMENT ON COLUMN employees.monthly_reports.avg_salary       IS 'Mean current salary across all active employees at generation time.';
COMMENT ON COLUMN employees.monthly_reports.generated_at     IS 'Wall-clock timestamp when the report was produced.';

-- ============================================================
-- STORED PROCEDURE: generate_monthly_report(report_date DATE)
-- Inserts one summary row and returns the new report_id
-- ============================================================
CREATE OR REPLACE FUNCTION employees.generate_monthly_report(p_report_date DATE)
RETURNS BIGINT
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_department_count  INTEGER;
    v_total_employees   INTEGER;
    v_avg_salary        DECIMAL(12,2);
    v_report_id         BIGINT;
BEGIN
    -- ── 1. Count all departments ──────────────────────────────
    SELECT COUNT(*)
    INTO   v_department_count
    FROM   employees.department;

    -- ── 2. Active employee count (current open-ended salary) ──
    SELECT COUNT(DISTINCT employee_id)
    INTO   v_total_employees
    FROM   employees.salary
    WHERE  to_date = '9999-01-01';

    -- ── 3. Average current salary ─────────────────────────────
    SELECT ROUND(AVG(amount)::NUMERIC, 2)
    INTO   v_avg_salary
    FROM   employees.salary
    WHERE  to_date = '9999-01-01';

    -- ── 4. Persist the report row (upsert on report_date) ─────
    INSERT INTO employees.monthly_reports
        (report_date, department_count, total_employees, avg_salary, generated_at)
    VALUES
        (p_report_date, v_department_count, v_total_employees, v_avg_salary, NOW())
    ON CONFLICT (report_date)
        DO UPDATE SET
            department_count = EXCLUDED.department_count,
            total_employees  = EXCLUDED.total_employees,
            avg_salary       = EXCLUDED.avg_salary,
            generated_at     = EXCLUDED.generated_at
    RETURNING report_id
    INTO v_report_id;

    RAISE NOTICE 'Report generated — id=%, date=%, depts=%, employees=%, avg_salary=%',
        v_report_id, p_report_date, v_department_count, v_total_employees, v_avg_salary;

    RETURN v_report_id;
END;
$$;

COMMENT ON FUNCTION employees.generate_monthly_report(DATE) IS
    'Generates a monthly executive summary snapshot. Accepts a logical report date and returns the new report_id.';
"}

